/* ===== Variables ===== */
:root {
  --primary: #e8590c;
  --primary-dark: #d9480f;
  --accent: #f59f00;
  --bg: #fff8f0;
  --surface: #ffffff;
  --dark: #2b1b12;
  --text: #54382a;
  --muted: #8a7364;
  --border: #f3e2d3;
  --shadow: 0 10px 30px rgba(232, 89, 12, .12);
