.btn-outline { background: transparent; color: var(--primary); border: 2px solid var(--primary); padding:.9rem 2rem; }
.btn-outline:hover { background: var(--primary); color:#fff; transform: translateY(-3px); }
.btn-whatsapp { background: #25d366; color:#fff; padding:.6rem 1.2rem; }
.btn-whatsapp:hover { background:#1ebe5b; transform: translateY(-2px); }
