document.querySelectorAll('.btn-wa').forEach(btn => {
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    const base = 'السلام عليكم، أود طلب:\n';
    const msg = btn.dataset.name
      ? base + `اسم المنتج: ${btn.dataset.name}\nالسعر: ${btn.dataset.price} ر.س`
      : base + btn.dataset.offer;
    const url = `https://wa.me/967509730421?text=${encodeURIComponent(msg)}`;
    window.open(url, '_blank');
  });
});
```
