Now JS file.

```js
/* ============================================================
   مطعم الشعلة - script.js
   تحكم القوائم، البحث، الفلاتر، الظهور، واتساب
   ============================================================ */

// ===== عناصر الواجهة =====
const navToggle = document.getElementById('navToggle');
const navMenu = document.getElementById('navMenu');
const siteHeader = document.getElementById('siteHeader');
const backToTop = document.getElementById('backToTop');
const searchInput = document.getElementById('menuSearch');
const categoryBtns = document.querySelectorAll('.category-btn');
const menuCards = document.querySelectorAll('.menu-card');
const emptyState = document.getElementById('emptyState');
const yearEl = document.getElementById('year');

// ===== فتح/إغلاق القائمة (الموبايل) =====
function closeNav() { ... }
navToggle.addEventListener('click', () => { navToggle.classList.toggle('open'); ... });
navMenu links click → closeNav.

// ===== تأثير الظهور عند التمرير (Scroll Reveal) =====
const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));

// ===== ترويسة ثابتة + ظهور زر العودة للأعلى =====
const handleScroll = () => {
  siteHeader.classList.toggle('scrolled', window.scrollY > 20);
  if (backToTop) backToTop.classList.toggle('show', window.scrollY > 400);
};
window.addEventListener('scroll', handleScroll, { passive: true });
handleScroll();

backToTop.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));

// ===== تحديد التصنيف الفعلي =====
categoryBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    categoryBtns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const cat = btn.dataset.category;
    menuCards.forEach(card => {
      const show = cat === 'all' || card.dataset.category === cat;
      card.style.display = show ? '' : 'none';
    });
  });
});

// ===== البحث داخل المنيو =====
let searchTimer;
searchInput.addEventListener('input', (e) => {
  clearTimeout(searchTimer);
  searchTimer = setTimeout(() => performSearch(e.target.value.trim()), 200);
});
function performSearch(query) {
  const q = query.toLowerCase();
  let visibleCount = 0;
  menuCards.forEach(card => {
    const name = (card.dataset.name || '').toLowerCase();
    const desc = (card.dataset.desc || '').toLowerCase();
    const match = !q || name.includes(q) || desc.includes(q);
    card.style.display = match ? '' : 'none';
    if (match) visibleCount++;
  });
  emptyState.classList.toggle('visible', visibleCount === 0);
}

// ===== زر واتساب =====
document.querySelectorAll('.btn-wa').forEach(btn => {
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    const message = btn.dataset.name
      ? `السلام عليكم، أود طلب:\nاسم المنتج: ${btn.dataset.name}\nالسعر: ${btn.dataset.price} ر.س`
      : `السلام عليكم، أود طلب:\n${btn.dataset.offer}`;
    window.open(`https://wa.me/967509730421?text=${encodeURIComponent(message)}`, '_blank');
  });
});

// ===== سنة التحديث في الفوتر =====
if (yearEl) yearEl.textContent = new Date().getFullYear();
```

